mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM notification n
    WHERE n.id = #{notificationId}
)

SELECT EXISTS (
    SELECT 1
    FROM notification n
    WHERE n.id = #{notificationId}
        AND n.target_user_id = #{userId}
)

mapper.update:
UPDATE notification
SET read_at = NOW()
WHERE id = #{notificationId}
    AND target_user_id = #{userId}
    AND read_at IS NULL
